using System;using System.IO;using System.Reflection;using System.Threading.Tasks;using System.Windows;using CodexStrip;
class TransposeTest {
 [STAThread]static void Main(){var app=new Application();var w=new StripWindow(true){Width=700,Height=360};app.MainWindow=w;w.Loaded+=async delegate{try{await Task.Delay(200);w.TransposeView();await Task.Delay(350);if(!w.Portrait||w.Width<320||w.Height<=w.Width)throw new Exception("floating transpose failed");w.Width=320;w.Height=900;w.ShowSettings();await Task.Delay(350);w.SetTheme("light");w.Snapshot("work/topmost-compact-light.png");w.SetTheme("dark");await Task.Delay(100);w.Snapshot("work/topmost-compact-dark.png");w.ClosePanel();await Task.Delay(350);
 typeof(StripWindow).GetField("DemoMode").SetValue(w,false);w.Config.ReserveWorkArea=true;w.Config.DockEdge="top";w.ApplyDockSettings();await Task.Delay(350);w.TransposeView();await Task.Delay(350);if(!w.Docked||!w.Portrait||w.Config.DockEdge!="left")throw new Exception("top to left failed");w.TransposeView();await Task.Delay(350);if(!w.Docked||w.Portrait||w.Config.DockEdge!="top")throw new Exception("left to top failed");w.Config.ReserveWorkArea=false;w.ApplyDockSettings();await Task.Delay(200);if(w.Docked)throw new Exception("float failed");File.WriteAllText("work/transpose-test.txt","PASS: real StripWindow floating transpose, top/left dock transpose and release; compact light/dark settings rendered");
 }catch(Exception e){File.WriteAllText("work/transpose-test.txt",e.ToString());}finally{typeof(StripWindow).GetField("DemoMode").SetValue(w,true);w.Close();}};app.Run(w);}
}
